// --- card builder, generated from n8n/lib/news-card.js — do not edit here ---
/**
 * The Adaptive Card posted to the Teams "Daily report" channel.
 *
 * Inlined into an n8n Code node by build-workflows.js, so no backticks and no
 * dollar-brace anywhere in this file.
 *
 * What it carries, and why in this order: the brief first, because someone
 * glancing at the channel wants the day in a sentence; then the articles that
 * went to the client, each with the same summary they read; then a handful more
 * that scored well but did not make the sheet, so the channel shows a little more
 * than the email rather than duplicating it exactly; then a button to the full
 * list as a PDF.
 *
 * Teams rejects a card over roughly 28KB with a generic failure, so the item
 * count is bounded and summaries are trimmed. Losing the card entirely because it
 * ran three articles too long would be a poor trade.
 */

var CARD_MAX_BYTES = 26000;
var SUMMARY_MAX = 190;
var TITLE_MAX = 120;

var esc = function (s) { return String(s == null ? '' : s); };

var trim = function (s, n) {
  var t = esc(s).replace(/\s+/g, ' ').trim();
  if (t.length <= n) return t;
  // Cut on a word so a truncated summary still reads as a sentence.
  var cut = t.slice(0, n);
  var sp = cut.lastIndexOf(' ');
  return (sp > n * 0.6 ? cut.slice(0, sp) : cut) + '…';
};

var shownDate = function (a) {
  var raw = a.shown_at || a.published_at || a.fetched_at;
  if (!raw) return '';
  var d = new Date(raw);
  if (isNaN(d.getTime())) return '';
  var s = d.toLocaleDateString('en-AU', { day: 'numeric', month: 'short', timeZone: 'Australia/Melbourne' });
  return a.date_is_exact === false ? s + ' (picked up)' : s;
};

/** One article: headline as a link, source and date beneath, then the summary. */
var itemBlock = function (a, accent) {
  var blocks = [{
    type: 'TextBlock',
    text: '[' + trim(a.title, TITLE_MAX).replace(/[\[\]]/g, '') + '](' + esc(a.url) + ')',
    wrap: true,
    weight: 'Bolder',
    size: 'Default',
    spacing: 'Medium',
    color: accent || 'Accent',
  }, {
    type: 'TextBlock',
    text: esc(a.source_name) + (shownDate(a) ? '  ·  ' + shownDate(a) : '')
          + (a.relevance_score != null ? '  ·  score ' + a.relevance_score : ''),
    wrap: true,
    isSubtle: true,
    size: 'Small',
    spacing: 'None',
  }];
  if (a.summary) {
    blocks.push({
      type: 'TextBlock', text: trim(a.summary, SUMMARY_MAX), wrap: true,
      size: 'Small', spacing: 'Small',
    });
  }
  return blocks;
};

var heading = function (text, sub) {
  var b = [{
    type: 'TextBlock', text: text, weight: 'Bolder', size: 'Medium',
    wrap: true, separator: true, spacing: 'Large',
  }];
  if (sub) b.push({ type: 'TextBlock', text: sub, isSubtle: true, size: 'Small', wrap: true, spacing: 'None' });
  return b;
};

/**
 * opts:
 *   coverage   the day being reported on, already formatted
 *   intro      the brief
 *   sent       articles that went out in the email
 *   extra      articles that scored well but did not make the sheet
 *   counts     { fetched, analysed, sources_contributing, sources_monitored }
 *   pdfUrl     the full list, in the channel's Files tab
 *   reportUrl  the dashboard
 */
var buildNewsCard = function (opts) {
  var o = opts || {};
  var sent = o.sent || [];
  var extra = o.extra || [];
  var counts = o.counts || {};

  var body = [
    { type: 'TextBlock', text: 'BEXT CONSULTANCY · INDUSTRY DAILY', size: 'Small',
      weight: 'Bolder', color: 'Accent', spacing: 'None' },
    { type: 'TextBlock', text: esc(o.coverage), size: 'ExtraLarge', weight: 'Bolder', wrap: true, spacing: 'None' },
    { type: 'TextBlock',
      text: sent.length + ' item' + (sent.length === 1 ? '' : 's') + ' sent to the client'
            + (counts.fetched ? '  ·  ' + counts.fetched + ' fetched' : '')
            + (counts.sources_contributing ? '  ·  ' + counts.sources_contributing
               + ' of ' + (counts.sources_monitored || '?') + ' sources contributed' : ''),
      isSubtle: true, size: 'Small', wrap: true, spacing: 'None' },
  ];

  if (o.intro) {
    body.push({
      type: 'Container', style: 'emphasis', bleed: false, spacing: 'Medium',
      items: [{ type: 'TextBlock', text: trim(o.intro, 700), wrap: true, size: 'Small' }],
    });
  }

  // Solar leads, because it is the business. Everything else energy-related
  // follows — the client was explicit that prioritising solar must not mean
  // dropping the rest, so this orders the card rather than filtering it.
  var solar = o.solar || [];
  var energy = o.energy || [];

  if (solar.length) {
    body = body.concat(heading('Solar', 'PV, storage, accreditation, standards and the schemes that fund them.'));
    for (var i = 0; i < solar.length; i++) body = body.concat(itemBlock(solar[i], 'Accent'));
  }

  if (energy.length) {
    body = body.concat(heading('Energy and buildings',
      'Efficiency, ratings, electrification, network and market news.'));
    for (var j = 0; j < energy.length; j++) body = body.concat(itemBlock(energy[j], 'Good'));
  }

  // Fallback for callers that still pass the older shape.
  if (!solar.length && !energy.length) {
    if (sent.length) {
      body = body.concat(heading('In today’s report', 'The same items, in the same order, as the emailed sheet.'));
      for (var k = 0; k < sent.length; k++) body = body.concat(itemBlock(sent[k], 'Accent'));
    }
    if (extra.length) {
      body = body.concat(heading('Also picked up',
        'Scored above the floor but below the cut for the sheet — shown here, not emailed.'));
      for (var n = 0; n < extra.length; n++) body = body.concat(itemBlock(extra[n], 'Good'));
    }
  }

  if (o.moreCount) {
    body.push({
      type: 'TextBlock', wrap: true, isSubtle: true, size: 'Small', spacing: 'Medium',
      text: o.moreCount + ' further article' + (o.moreCount === 1 ? '' : 's') + ' were retrieved. '
          + 'The full list is in the PDF, and everything is on the dashboard.',
    });
  }

  var actions = [];
  if (o.pdfUrl) actions.push({ type: 'Action.OpenUrl', title: 'View more — everything fetched', url: o.pdfUrl });
  if (o.reportUrl) actions.push({ type: 'Action.OpenUrl', title: 'Open the dashboard', url: o.reportUrl });

  var card = {
    type: 'AdaptiveCard',
    $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
    version: '1.4',
    msteams: { width: 'Full' },
    body: body,
    actions: actions,
  };

  // Teams fails a card over its size limit with a generic error, so drop the
  // optional half from the end until it fits rather than lose the post.
  var size = function () { return JSON.stringify(card).length; };
  while (size() > CARD_MAX_BYTES && extra.length) {
    extra.pop();
    card.body = card.body.slice(0, card.body.length - 3);
  }
  while (size() > CARD_MAX_BYTES && card.body.length > 8) {
    card.body = card.body.slice(0, card.body.length - 3);
    card.body.push({ type: 'TextBlock', size: 'Small', isSubtle: true, wrap: true,
      text: 'Trimmed to fit the Teams card limit — the full list is in the PDF.' });
  }

  return card;
};

/** Teams expects the card wrapped in an attachment envelope, not on its own. */
var newsCardEnvelope = function (card) {
  return {
    type: 'message',
    attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', content: card }],
  };
};



// --- end card builder ---

// --- fetch list, generated from n8n/lib/fetch-list.js — do not edit here ---
/**
 * The day's full fetch list, as HTML for the PDF that hangs off the Teams card.
 *
 * Inlined into an n8n Code node, so no backticks and no dollar-brace.
 *
 * Two zones, which is the whole design:
 *
 *   Everything scoring 20 or above, in full — source, headline, link, score.
 *   Roughly fifty a day. This is where a scorer mistake would actually matter,
 *   so it is all visible and checkable.
 *
 *   Below 20, a per-source tally only. Fifty-eight per cent of what we fetch
 *   scores under twenty, and that band is where the tobacco bill lived — the
 *   material the client complained about. Printing sixty-five rows of it daily
 *   would recreate that complaint in a new place, while hiding it entirely would
 *   lose the proof that a source was fetched at all. A count does both jobs.
 */

var FULL_DETAIL_FLOOR = 20;

var esc = function (s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};

var trim = function (s, n) {
  var t = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  return t.length <= n ? t : t.slice(0, n - 1) + '…';
};

var band = function (score) {
  if (score >= 70) return '#0f766e';
  if (score >= 40) return '#1e40af';
  return '#6b7280';
};

/**
 * rows: { source_name, category, title, url, relevance_score, summary, in_report }
 * meta: { coverage, floor, fetched, sources_monitored }
 */
var buildFetchList = function (rows, meta) {
  var m = meta || {};
  var all = rows || [];
  var detail = all.filter(function (r) { return (r.relevance_score || 0) >= FULL_DETAIL_FLOOR; });
  var quiet = all.filter(function (r) { return (r.relevance_score || 0) < FULL_DETAIL_FLOOR; });

  detail.sort(function (a, b) {
    return (b.relevance_score || 0) - (a.relevance_score || 0)
      || String(a.source_name).localeCompare(String(b.source_name));
  });

  var rowsHtml = detail.map(function (r) {
    var mark = r.in_report
      ? '<span style="background:#0f766e;color:#fff;font:600 9px Arial;padding:2px 5px;border-radius:3px">SENT</span>'
      : '';
    return '<tr style="border-bottom:1px solid #eef0f3">'
      + '<td style="padding:7px 8px 7px 0;vertical-align:top;width:34px">'
      + '<span style="font:700 12px Arial;color:' + band(r.relevance_score) + '">'
      + (r.relevance_score == null ? '–' : r.relevance_score) + '</span></td>'
      + '<td style="padding:7px 8px 7px 0;vertical-align:top">'
      + '<a href="' + esc(r.url) + '" style="font:600 11.5px Arial;color:#0f766e;text-decoration:none">'
      + esc(trim(r.title, 118)) + '</a> ' + mark
      + '<div style="font:10px Arial;color:#9aa3af;margin-top:2px">' + esc(r.source_name)
      + (r.category ? ' · ' + esc(r.category) : '') + '</div>'
      + (r.summary ? '<div style="font:10.5px/1.45 Arial;color:#4b5563;margin-top:3px">'
          + esc(trim(r.summary, 210)) + '</div>' : '')
      + '</td></tr>';
  }).join('');

  // Below the detail floor: how many, from where. Sorted by volume so an unusual
  // day stands out.
  var tally = {};
  for (var i = 0; i < quiet.length; i++) {
    var k = quiet[i].source_name || 'unknown';
    tally[k] = (tally[k] || 0) + 1;
  }
  var tallyRows = Object.keys(tally)
    .sort(function (a, b) { return tally[b] - tally[a] || a.localeCompare(b); })
    .map(function (k) {
      return '<tr><td style="padding:3px 12px 3px 0;font:10.5px Arial;color:#4b5563">' + esc(k) + '</td>'
        + '<td style="padding:3px 0;font:10.5px Arial;color:#9aa3af">' + tally[k] + '</td></tr>';
    }).join('');

  return '<!doctype html><html><head><meta charset="utf-8"></head>'
    + '<body style="margin:0;padding:26px 30px;font-family:Arial,sans-serif;color:#111827">'
    + '<div style="font:10px Arial;letter-spacing:.14em;text-transform:uppercase;color:#9aa3af">'
    + 'BEXT Consultancy · Industry Daily</div>'
    + '<h1 style="font:600 17px Arial;margin:4px 0 2px">Everything fetched — ' + esc(m.coverage || '') + '</h1>'
    + '<div style="font:10.5px Arial;color:#9aa3af;margin-bottom:16px">'
    + all.length + ' articles retrieved'
    + (m.sources_monitored ? ' across ' + m.sources_monitored + ' monitored sources' : '')
    + ' · items scoring ' + (m.floor || 40) + '+ went to the client, marked SENT</div>'

    + '<h2 style="font:600 12px Arial;margin:18px 0 6px;padding-bottom:4px;'
    + 'border-bottom:2px solid #14b8a6">Scored ' + FULL_DETAIL_FLOOR + ' and above'
    + ' <span style="font:400 10px Arial;color:#9aa3af">(' + detail.length + ')</span></h2>'
    + '<table style="width:100%;border-collapse:collapse">' + rowsHtml + '</table>'

    + (quiet.length
      ? '<h2 style="font:600 12px Arial;margin:22px 0 6px;padding-bottom:4px;'
        + 'border-bottom:2px solid #d1d5db">Below ' + FULL_DETAIL_FLOOR
        + ' <span style="font:400 10px Arial;color:#9aa3af">(' + quiet.length
        + ' — counted, not listed)</span></h2>'
        + '<div style="font:10px Arial;color:#9aa3af;margin-bottom:6px">'
        + 'Retrieved and scored as not relevant. Shown as counts so coverage is provable '
        + 'without filling the document with material the scorer already rejected.</div>'
        + '<table style="border-collapse:collapse">' + tallyRows + '</table>'
      : '')

    + '<div style="margin-top:24px;padding-top:10px;border-top:1px solid #e5e7eb;'
    + 'font:9.5px Arial;color:#9aa3af">Generated by the BEXT automation platform. '
    + 'Scores are the relevance model\'s, not a human judgement.</div>'
    + '</body></html>';
};



// --- end fetch list ---

const rows = $input.all().map(i => i.json);
if (!rows.length || !rows[0].report_date) {
  return [{ json: { skip: true, detail: 'no sent report to accompany' } }];
}

const day = rows[0].report_date;
const coverage = new Date(day).toLocaleDateString('en-AU',
  { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Australia/Melbourne' });

const FLOOR = Number($env.REPORT_MIN_RELEVANCE || 40);

// Everything that cleared the floor, best first.
const qualifying = rows
  .filter(r => r.relevance_score >= FLOOR)
  .sort((a, b) => b.relevance_score - a.relevance_score);

// Solar leads the card because it is the business. Detected from the text rather
// than from the source, since solar stories arrive from regulators, the trade
// press and the Minister's office alike — and a source-based split would put a
// PV standards change under "energy" merely because the AER published it.
// Escaped as \\b because this lives inside a template literal: a single \b is
// read as a backspace character before it ever reaches the regex, so the pattern
// silently requires a backspace before "solar" and matches nothing. It reported
// "0 solar" on a day carrying a new inverter standard and a PV module changeover.
const SOLAR = /\b(solar|photovoltaic|pv|rooftop|inverter|feed-?in|batter(y|ies)|storage|behind[- ]the[- ]meter|solar panel)\b/i;
const isSolar = r => SOLAR.test(String(r.title || '') + ' ' + String(r.summary || ''));

const solar = qualifying.filter(isSolar).slice(0, 5);
const solarUrls = new Set(solar.map(r => r.url));
// The rest of the energy material. Prioritising solar orders the card; it does
// not remove anything, which the client was explicit about.
const energy = qualifying.filter(r => !solarUrls.has(r.url)).slice(0, 15);

const shown = solar.length + energy.length;

// The "View more" button opens the full list from the dashboard, gated by a
// token in the URL. SharePoint could not serve it — anonymous sharing is disabled
// and an org link needs a Microsoft session the Teams in-app browser lacks — so
// the list lives on the dashboard, which is where the client asked for it anyway.
const viewUrl = 'https://bext.dev-environment.site/api/fetched?date=' + day
  + '&token=' + ($env.FETCH_VIEW_TOKEN || '');

const card = buildNewsCard({
  coverage,
  solar,
  energy,
  moreCount: Math.max(0, rows.length - shown),
  counts: {
    fetched: rows.length,
    sources_contributing: new Set(rows.map(r => r.source_name)).size,
    sources_monitored: rows[0].sources_monitored,
  },
  pdfUrl: viewUrl,
  reportUrl: 'https://bext.dev-environment.site/reports',
});

const listHtml = buildFetchList(rows, {
  coverage, floor: FLOOR, sources_monitored: rows[0].sources_monitored,
});

return [{ json: {
  skip: false,
  report_date: day,
  coverage,
  card,
  listHtml,
  counts: { fetched: rows.length, solar: solar.length, energy: energy.length, shown: shown },
} }];

// Post the card to the channel. The "View more" button already points at the
// dashboard fetch list (set in the previous node); the list itself was stored to
// the reports row by the node between, so it is there when the button is clicked.
//
// SharePoint used to host the list as a PDF, and it did not open for the client:
// the site disables anonymous sharing and an org link needs a Microsoft session
// the Teams in-app browser does not carry. The dashboard route has neither
// constraint.
// Named explicitly: this node runs after the Postgres store, and a Postgres node
// emits its query result, not the payload. $input here would be the UPDATE's
// output, with no card in it.
const d = $('Build card and list').first().json;
if (d.skip) return [{ json: { ok: true, detail: 'skipped: ' + d.detail } }];

const helpers = this.helpers;
const hook = $env.TEAMS_DAILY_WEBHOOK_URL;
if (!hook) return [{ json: { ok: false, detail: 'TEAMS_DAILY_WEBHOOK_URL not set' } }];

await helpers.httpRequest({
  method: 'POST', url: hook, json: true, timeout: 60000,
  body: { type: 'message', attachments: [
    { contentType: 'application/vnd.microsoft.card.adaptive', content: d.card } ] },
});

return [{ json: { ok: true, detail:
  d.counts.solar + ' solar, ' + d.counts.energy + ' energy, ' + d.counts.fetched + ' fetched' } }];
